import java.util.*;

class Solution {
  public int[] assignBikes(int[][] workers, int[][] bikes) {
    // bucket every pair by distance; within a bucket pairs are added in (worker, bike) order
    List<List<int[]>> buckets = new ArrayList<>();
    for (int d = 0; d <= 2000; d++) buckets.add(new ArrayList<>());
    for (int w = 0; w < workers.length; w++)
      for (int b = 0; b < bikes.length; b++) {
        int d = Math.abs(workers[w][0] - bikes[b][0]) + Math.abs(workers[w][1] - bikes[b][1]);
        buckets.get(d).add(new int[] {w, b});
      }
    int[] ans = new int[workers.length];
    Arrays.fill(ans, -1);
    boolean[] taken = new boolean[bikes.length];
    int assigned = 0;
    for (List<int[]> bucket : buckets) {
      for (int[] p : bucket) {
        if (ans[p[0]] != -1 || taken[p[1]]) continue;
        ans[p[0]] = p[1];
        taken[p[1]] = true;
        if (++assigned == workers.length) return ans;
      }
    }
    return ans;
  }
}
